-- ENV-BACKFILL-002 — carbon-domain backfill (claim ENV-BACKFILL-002-C1, Track-Z GLM)
-- Work order: docs/work-orders/ENV-BACKFILL-002.md · ONE migration (WO §4.5 pinned filename).
--
-- WHAT (D1-decided, receipts verbatim in docs/ai/handoffs/ENV-BACKFILL-002-GLM.md):
--   (1) additive column carbon.reading.activity_subtype (fork B — enum untouched);
--   (2) 26 activity-series meters (grid electricity, solar use/gen ×5, water ×2,
--       diesel ×2, gasoline, LPG, paper ×2, chlorine, ink, waste ×10);
--   (3) 1,054 guarded reading rows (master 1,037 merged groups + waterin +11 + ink +6);
--   (4) carbon.waste_sale_ledger — genuinely-new waste-sale money ledger (27 rows);
--   (5) NO touch on: live 907 reading rows / plant meter, emission_factor (12),
--       wastewater.*, chemical.*, fuel.*, garbage.*, any view, RLS of existing tables.
--
-- D1 PINS (evidence-backed):
--   dedup key (meter_id, reading_date) = the existing UNIQUE constraint; every
--   INSERT is guarded WHERE NOT EXISTS on exactly that key (re-run ⇒ 0 rows).
--   consumption column carries ONLY the grid-electricity series (kWh); every
--   other series stores its quantity in meter_value with consumption NULL —
--   carbon.v_unified_co2e arm-1 and carbon.v_overview_carbon treat ALL
--   consumption as grid electricity, so non-kWh quantities must never land there.
--   Multi-row (series,date) groups (405, waste logged per department): one
--   reading, meter_value = arithmetic sum of the sheet's own same-date rows,
--   full per-row breakdown in raw_payload marked merged_sum. Never re-derived
--   beyond that stated-row aggregation; computed-looking columns (ค่าใช้จ่าย,
--   ยอดรวมเหลือ) stored as-written or NULL — never recomputed.
--   Electricity 5 version-conflict dates: the dedicated energy tab's value is
--   the reading; small companion rows preserved verbatim in raw_payload
--   (companion_rows, recorded_not_aggregated).
--   Dates: all seeded tabs are ค.ศ. d/m/yyyy (day-first, re-proven at D2);
--   blanks → NULL; unknown ≠ zero. The ledger's 21/01/2025 date is stored
--   as written (recorded source anomaly).
--   PII: ink สถานที่ column omitted from storage; the ledger note containing a
--   personal name stored NULL (masked, recorded). No 13-digit pattern seeded.
--
-- ROLLBACK (owner-gated; NOT executed by this migration):
--   DELETE FROM carbon.reading WHERE raw_payload->>'provenance' = 'ENV-BACKFILL-002';
--   DELETE FROM carbon.waste_sale_ledger WHERE provenance LIKE 'ENV-BACKFILL-002%';
--   DROP TABLE IF EXISTS carbon.waste_sale_ledger;
--   DELETE FROM carbon.meter WHERE meter_name IN ( -- the 26 names below
--     'การใช้ไฟฟ้าส่วนภูมิภาค (บิล รพ.อุทัย — ENV-BACKFILL-002)', ...);
--   ALTER TABLE carbon.reading DROP COLUMN IF EXISTS activity_subtype; -- last, owner-gated
--
-- Existing policies govern seed writes (seed runs as table owner); the new
-- ledger table mirrors the carbon domain's RLS posture (permissive ALL to
-- authenticated) on the NEW table only.

alter table carbon.reading add column if not exists activity_subtype text;
comment on column carbon.reading.activity_subtype is 'ENV-BACKFILL-002: sheet ActivityType verbatim (source vocabulary); NULL for rows outside the backfill.';
