-- ── carbon.waste_sale_ledger: genuinely-new fragment (WO §6 decision LEDGER) ──
create table if not exists carbon.waste_sale_ledger (
  id uuid primary key default gen_random_uuid(),
  entry_seq smallint not null,
  entry_date date,
  balance_before numeric,
  amount_in numeric,
  amount_out numeric,
  note text,
  balance_recorded numeric,
  provenance text not null default 'ENV-BACKFILL-002 (sheet เงินขายขยะ ledger, 2026-11-24 share)',
  created_at timestamptz not null default now()
);
comment on table carbon.waste_sale_ledger is 'ENV-BACKFILL-002: waste-sale revenue ledger — ยอดรวมเหลือ stored as-written, never recomputed; one personal-name note masked NULL (D1 PII rule).';
do $$
begin
  if not exists (select 1 from pg_policies
                 where schemaname = 'carbon' and tablename = 'waste_sale_ledger'
                   and policyname = 'carbon_waste_sale_ledger_rw') then
    create policy carbon_waste_sale_ledger_rw on carbon.waste_sale_ledger
      for all to authenticated using (true) with check (true);
  end if;
end $$;
alter table carbon.waste_sale_ledger enable row level security;
